/** Tools with no official open vector mark — the UI shows a neutral monogram instead of guessing. */
export const iconFallbacks = ["loki", "alertmanager", "freepbx"];

export function getIcon(slug: string): BrandIcon {
  return brandIcons[slug] ?? { title: slug, viewBox: "0 0 24 24", svg: "" };
}
